def dump(name, obj):
    (BASE / name).write_text(json.dumps(obj, ensure_ascii=False, indent=2) + '\n')

def table(headers, rows):
    return '<div class="table-wrap"><table class="cols-'+str(len(headers))+'"><thead><tr>' + ''.join('<th>'+html.escape(x)+'</th>' for x in headers) + '</tr></thead><tbody>' + ''.join('<tr>'+''.join('<td>'+str(v)+'</td>' for v in row)+'</tr>' for row in rows) + '</tbody></table></div>'

def section(key, title, body):
    return f'<section id="{key}"><h2>{title}</h2>{body}</section>'

